const fs=require('fs');
const plan=JSON.parse(fs.readFileSync('shift-plan.json'));
const rel=JSON.parse(fs.readFileSync('release.json'));
const night=JSON.parse(fs.readFileSync('night.json'));
const limits=[80,40,50,70];
const actual=plan.acKw.map((p,i)=>Math.min(p,limits[i]));
const dep=[night.buses[0].startKwh+night.buses[0].untilSlot*0+0.5*0.9*(actual[0]+actual[1]), night.buses[1].startKwh+0.5*0.9*(actual[2]+actual[3])];
console.log({plan:plan.acKw,limits,actual,dep,within:plan.acKw.every((p,i)=>p<=limits[i])});
console.log('release',rel);
const assert=(c,m)=>{if(!c)throw new Error(m)};
assert(JSON.stringify(rel.departureKwh)===JSON.stringify(dep),'departure mismatch');
assert(JSON.stringify(rel.marginKwh)===JSON.stringify([0,0]),'margin mismatch');
assert(rel.at90.A==='GO'&&rel.at90.B==='GO','at90 mismatch');
assert(rel.at85.A==='HOLD'&&rel.at85.B==='HOLD','at85 mismatch');
assert(rel.evidenceSha==='341e19e288de9f561f85fcb66a7a910ff6f3e143','evidence mismatch');
console.log('release checks OK');
EOF
